from pathlib import Path
import re
root=Path('dist')
services=[('production','Production','THE CLAW / FORM','From the first plan to the final take.','Shoot planning, crew, equipment, locations and on-set execution.'),('film','Film','THE EYE / VISION','A point of view worth following.','Concepts, visual treatments, direction and narrative filmmaking.'),('editing','Editing','THE FANG / PRECISION','The story lives between the frames.','Editing, colour, sound and finishing for the final screen.'),('brand-shoot','Brand Shoot','THE COAT / IDENTITY','An identity you can feel.','Product, lifestyle and campaign imagery with a distinct visual language.'),('marketing','Marketing','THE ROAR / REACH','Give the story a world to move through.','Campaign direction, social content, launch planning and creative distribution.'),('film-investment','Film Investment','THE SPARK / POSSIBILITY','A conversation that starts a film.','Project pitches, production planning, budget review and potential partnerships.')]
def gallery():
 return '<section class="art-gallery" aria-label="Explore six service artworks">'+''.join('<article class="art-item"><div class="art-visual"><canvas class="service-art" data-art="'+slug+'" aria-label="Animated '+name+' artwork"></canvas><span class="art-coordinate">P.'+str(i+1).zfill(2)+' / '+motif+'</span><span class="art-live"><i></i> LIVE STUDY</span></div><details class="art-detail"><summary><span class="art-name">'+name+'</span><span class="art-more">MORE DETAILS <b>+</b></span></summary><div class="art-description"><p>'+tag+'</p><small>'+desc+'</small><a href="service-'+slug+'.html">EXPLORE '+name.upper()+' ↗</a></div></details></article>' for i,(slug,name,motif,tag,desc) in enumerate(services))+'</section>'
exhibit='''<section class="service-exhibit" id="service-exhibit"><div class="exhibit-stage"><div class="exhibit-header"><span>P / CREATIVE DISCIPLINES</span><a href="services.html">VIEW THE COLLECTION ↗</a></div><div class="exhibit-art"><canvas class="service-art" data-art="production" data-exhibit="true" aria-label="Interactive Panther service artwork"></canvas></div><div class="exhibit-copy"><span class="eyebrow" id="exhibit-motif">THE CLAW / FORM</span><h2 id="exhibit-title">Production</h2><p id="exhibit-tag">From the first plan to the final take.</p><a href="service-production.html" id="exhibit-link">EXPLORE SERVICE ↗</a></div><div class="exhibit-nav" aria-label="Choose a service">'''+''.join('<button data-service-index="'+str(i)+'" class="'+('active' if i==0 else '')+'"><span>0'+str(i+1)+'</span>'+name+'</button>' for i,(_,name,*_) in enumerate(services))+'''</div><div class="exhibit-footer"><span id="exhibit-counter">01 / 06</span><span>SCROLL THROUGH THE COLLECTION ↓</span></div></div></section>'''
for p in root.glob('*.html'):
 s=p.read_text()
 if p.name=='services.html':
  a=s.index('<main>');b=s.index('</main>');s=s[:a]+'''<main><section class="collection-lead"><span class="collection-label">PANTHER / THE COLLECTION</span><h1>CRAFT IN<br><em>MOTION.</em><sup>06</sup></h1><div class="collection-intro"><p>Six creative disciplines. Six living studies.<br>Explore the instinct behind each service.</p><button class="art-motion" aria-pressed="true">PAUSE ART Ⅱ</button></div></section>'''+gallery()+'''<section class="collection-end"><h2>ONE INSTINCT.<br>EVERY POSSIBILITY.</h2><a class="contact-button" href="contact.html">START A PROJECT ↗</a></section></main>'''+s[b+7:]
 if p.name=='index.html':s=re.sub(r'<section class="section home-services">.*?</section>',exhibit,s,flags=re.S)
 if p.name.startswith('service-'):
  slug=p.stem[8:];s=s.replace('<section class="service-feature"><img src="assets/'+('desert.jpg' if slug in ['film','brand-shoot','film-investment'] else 'set.jpg')+'" alt="', '<section class="service-feature"><img src="assets/'+('desert.jpg' if slug in ['film','brand-shoot','film-investment'] else 'set.jpg')+'" alt="')
  s=re.sub(r'(<section class="service-feature">)<img[^>]+>',r'\1<div class="detail-art"><canvas class="service-art" data-art="'+slug+'" aria-label="'+slug+' generative artwork"></canvas></div>',s)
  s=s.replace('<section class="page-lead panther-lead">','<section class="page-lead panther-lead art-service-lead">')
 if p.name in ('index.html','work.html'):
  s=s.replace('src="assets/set.jpg" alt="Camera and studio lighting detail"','src="assets/campaign.jpg" alt="Fashion campaign concept in a dark architectural setting"')
  s=s.replace('The quiet force','Quiet force').replace('A brand-film concept built around texture, restraint and a powerful visual identity.','A fashion campaign concept exploring identity, architecture and light.')
 s=s.replace('<script src="app.js"></script>','<script src="app.js"></script><script src="art.js"></script>')
 # Compact, deliberate studio navigation with an expandable service directory.
 s=s.replace('<a href="services.html">Services</a></nav>','<a href="services.html">Services</a></nav>')
 p.write_text(s)
